var BASE_DECISAO = 'https://n8n.modal.org.br/webhook/captacao-decisao';
var BASE_REGISTRO = 'https://n8n.modal.org.br/webhook/captacao-decisao-registrar';
var TG_ENVIO = 'https://discricionarias.transferegov.sistema.gov.br/';
