var RODAPE = 'Mensagem automática da captação de oportunidades do Instituto Modal.';
var ROTULO_PARCEIRA = 'Em parceria com uma empresa (cliente ou parceiro do Modal)';

var REC = { seguir: 'Seguir', avaliar: 'Avaliar', nao_seguir: 'Não seguir' };
var ESF = { baixo: 'Baixo', medio: 'Médio', alto: 'Alto' };
var SIT = { nova: 'Sem resposta', avisada: 'Sem resposta', concorrer: 'Vamos concorrer', talvez: 'Talvez', nao_serve: 'Não serve', enviada: 'Proposta enviada', ganhou: 'Ganhou', perdeu: 'Perdeu', desistiu: 'Desistiu' };
var DECIDIVEL = ['nova', 'avisada', 'talvez', 'concorrer'];
var CERTS = {
  federal: { nome: 'Certidão de débitos federais (Receita Federal e PGFN)', url: 'https://servicos.receitafederal.gov.br/servico/certidoes/', nota: 'informe o CNPJ; sai na hora quando não há pendência.' },
  fgts: { nome: 'Certificado de Regularidade do FGTS (CRF, Caixa)', url: 'https://consulta-crf.caixa.gov.br/consultacrf/pages/consultaEmpregador.jsf', nota: 'vale 30 dias e só pode ser renovado a partir de 5 dias antes de vencer: por isso é emitido perto da entrega.' },
  trabalhista: { nome: 'Certidão Negativa de Débitos Trabalhistas (CNDT, TST)', url: 'https://cndt-certidao.tst.jus.br/inicio.faces', nota: 'informe o CNPJ.' },
  df: { nome: 'Certidão negativa de débitos do Distrito Federal (Receita do DF, Secretaria de Economia)', url: 'https://ww1.receita.fazenda.df.gov.br/cidadao/certidoes/Certidao', nota: 'confira a validade impressa na certidão.' }
};
var ORDEM_CERT = ['federal', 'fgts', 'trabalhista', 'df'];

function txt(v) { return String(v == null ? '' : v).trim(); }
function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;'); }
// Só endereço público (mesma trava da triagem): o link do edital vem do texto lido pela IA e não pode levar o robô a serviço interno.
function enderecoPublico(u) {
  var m = String(u || '').trim().match(/^https?:\/\/([^\/?#:@]+)(:(?:80|443))?([\/?#]|$)/i);
  if (!m) return false;
  var h = m[1].toLowerCase().replace(/\.$/, '');
  // Nome de domínio comum: rótulos só com letras, números e hífen, terminando em domínio de letras
  // (recusa IP em qualquer grafia, como 0x7f.0.0.1 ou 0177.1, barra invertida e %).
  if (!/^([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,63}$/.test(h)) return false;
  if (/(^|\.)(localhost|local|internal|lan|home|arpa)$/.test(h)) return false;
  if (/(^|\.)modal\.org\.br$/.test(h)) return false;
  return true;
}
function seguro(u) { var v = txt(u); return /^https?:\/\/[^\s"'<>]+$/i.test(v) && enderecoPublico(v) ? v : ''; }
function normTxt(s) { return String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim(); }
function tam(s) { return String(s || '').replace(/\s+/g, '').length; }
function itensDe(v) { return (Array.isArray(v) ? v : String(v || '').split('\n')).map(function (s) { return String(s).replace(/^[-•*\s]+/, '').trim(); }).filter(Boolean); }

// ---------- datas (AAAA-MM-DD, fuso de São Paulo, sem horário de verão desde 2019) ----------
function dia(v) {
  if (v == null || v === '') return '';
  if (Object.prototype.toString.call(v) === '[object Date]') v = v.toISOString();
  var s = String(v).trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  var t = Date.parse(s);
  if (isNaN(t)) { var m = s.match(/^(\d{4}-\d{2}-\d{2})/); return m ? m[1] : ''; }
  return new Date(t - 3 * 3600 * 1000).toISOString().slice(0, 10);
}
function utc(iso) { return Date.parse(iso + 'T00:00:00Z'); }
function diasEntre(a, b) { return Math.round((utc(b) - utc(a)) / 86400000); }
function somaDias(iso, n) { return new Date(utc(iso) + n * 86400000).toISOString().slice(0, 10); }
function br(iso) { var m = String(iso || '').match(/^(\d{4})-(\d{2})-(\d{2})/); return m ? m[3] + '/' + m[2] + '/' + m[1] : ''; }
function faltam(n) { return n <= 0 ? 'é hoje' : n === 1 ? 'falta 1 dia' : 'faltam ' + n + ' dias'; }
function porPrazo(a, b) { return (a.prazo || '9999-12-31').localeCompare(b.prazo || '9999-12-31'); }

// ---------- execução: produção x teste ----------
// Produção = fluxo gerado com --producao (modoTeste false) E execução agendada. Manual ou modoTeste: e-mail só para o endereço de teste,
// com [TESTE] no assunto, e só oportunidades "[TESTE]" têm a situação alterada. Em produção, "[TESTE]" é ignorado.
function contexto(cfg, modoN8n) {
  var agendada = modoN8n === 'production' || modoN8n === 'trigger';
  var producao = cfg.modoTeste === false && agendada;
  return { producao: producao, para: producao ? cfg.lista : cfg.emailTeste, prefixo: producao ? '' : '[TESTE] ' };
}
function ehTeste(op) { return /^\s*\[TESTE\]/i.test(txt(op.titulo)) || /^\s*\[TESTE\]/i.test(txt(op.titulo_oficial)); }

// ---------- oportunidade ----------
function ehApiTransferegov(u) { return /^https?:\/\/api-publica\.transferegov\./i.test(txt(u)); }
// Link para leitura de gente. Programa do Transferegov não tem página pública (a API devolve JSON): vai o caminho de envio e a instrução de busca.
function linkOp(op) {
  var cands = [seguro(op.link_edital_oficial), seguro(op.url)].filter(Boolean);
  var normal = cands.filter(function (u) { return !ehApiTransferegov(u); })[0] || '';
  var prog = txt(op.tipo_oportunidade) === 'programa_aberto';
  if (normal) return { tg: false, url: normal, rotulo: prog ? 'Programa' : 'Edital oficial' };
  if (cands.some(ehApiTransferegov) || prog) return { tg: true, url: TG_ENVIO, rotulo: TG_ROTULO };
  return { tg: false, url: '', rotulo: 'Edital oficial' };
}
function infoOp(op) {
  return {
    chave: txt(op.chave), titulo: txt(op.titulo_oficial) || txt(op.titulo), ofertante: txt(op.ofertante), prazo: dia(op.prazo), valor: txt(op.valor),
    resumo: txt(op.resumo), publico: txt(op.publico_elegivel), papel: txt(op.papel_modal), fonte: txt(op.fonte), prog: txt(op.tipo_oportunidade) === 'programa_aberto',
    link: linkOp(op), teste: ehTeste(op)
  };
}
function papelRotulo(papel) {
  if (papel === 'parceira') return ROTULO_PARCEIRA;
  if (papel === 'proponente') return 'O Modal pode ser o proponente (ICT)';
  return 'Papel do Modal a confirmar no edital';
}

// ---------- blocos de e-mail (formato do subfluxo "Modal – Enviar e-mail") ----------
function P(html) { return { tipo: 'paragrafo', html: html }; }
function PT(texto) { return { tipo: 'paragrafo', texto: texto }; }
function H(texto) { return { tipo: 'subtitulo', texto: texto }; }
function UL(itens) { return { tipo: 'lista', itens: itens }; }
function AV(texto, tom) { return { tipo: 'aviso', texto: texto, tom: tom || 'atencao' }; }
function CAMPOS(itens, titulo) { return { tipo: 'campos', titulo: titulo, itens: itens }; }
function BOTOES(itens) { return { tipo: 'botoes', itens: itens }; }
function blocoLink(op) {
  var i = op.link ? op : infoOp(op);
  if (i.link.tg) return P('<b>Programa no Transferegov:</b> <a href="' + esc(i.link.url) + '">' + esc(i.link.rotulo) + '</a>. No portal, busque pelo nome do programa: <i>' + esc(i.titulo) + '</i>.');
  if (i.link.url) return P('<b>' + esc(i.prog ? 'Programa oficial' : 'Edital oficial') + ':</b> <a href="' + esc(i.link.url) + '">' + esc(i.link.url) + '</a>');
  return PT('Link do edital não identificado; procure no site do ofertante.');
}
function urlDecisao(token, d) { return BASE_DECISAO + '?t=' + encodeURIComponent(token) + '&d=' + d; }
function botoesDecisao(token) { return BOTOES([{ rotulo: 'Vamos concorrer', url: urlDecisao(token, 'concorrer') }, { rotulo: 'Talvez', url: urlDecisao(token, 'talvez') }, { rotulo: 'Não serve', url: urlDecisao(token, 'nao_serve') }]); }
function novoEmail(cfg, ctx, e) {
  return {
    para: ctx.para, assunto: ctx.prefixo + e.assunto, nomeRemetente: cfg.remetente, responderPara: cfg.lista,
    etiqueta: e.etiqueta, titulo: e.titulo, previa: e.previa, blocos: e.blocos, rodape: RODAPE, _marca: e.marca || null
  };
}

// ---------- resposta do subfluxo de e-mail ----------
// O subfluxo devolve a resposta do Gmail (tem "id") ou falha. Só conta como enviado o que voltou com id.
function enviado(resp) { return !!(resp && typeof resp === 'object' && !resp.error && typeof resp.id === 'string' && resp.id); }

// Captação – Decisão: página de confirmação (GET) e registro (POST). Funções puras; embutido depois de comum.js.
// GET nunca grava (leitores de e-mail e antivírus abrem links sozinhos); só o POST, vindo do botão da página, grava.

var DECISOES = ['concorrer', 'talvez', 'nao_serve', 'enviada', 'ganhou', 'perdeu', 'desistiu'];
var ABERTAS = ['nova', 'avisada', 'talvez', 'concorrer'];
// Transições permitidas. Não serve, ganhou, perdeu e desistiu são finais.
var TRANS = { concorrer: ABERTAS, talvez: ABERTAS, nao_serve: ABERTAS, enviada: ['concorrer'], desistiu: ['concorrer', 'enviada'], ganhou: ['enviada'], perdeu: ['enviada'] };
var FINAIS = ['nao_serve', 'ganhou', 'perdeu', 'desistiu'];
var ROT = { concorrer: 'Vamos concorrer', talvez: 'Talvez', nao_serve: 'Não serve', enviada: 'Enviamos a proposta', ganhou: 'Ganhamos', perdeu: 'Perdemos', desistiu: 'Desistimos' };
var SIT_PAGINA = { concorrer: 'Vamos concorrer', talvez: 'Talvez', nao_serve: 'Não serve', nova: 'Ainda sem resposta', avisada: 'Ainda sem resposta', enviada: 'Proposta enviada', ganhou: 'Ganhou', perdeu: 'Perdeu', desistiu: 'Desistiu' };
var OPCOES_NS = { fora_perfil: 'Fora do perfil', prazo_curto: 'Prazo curto', falta_documentacao: 'Falta documentação', valor_baixo: 'Valor baixo', outro: 'Outro' };
var OPCOES_DES = { prazo_curto: 'Prazo curto', falta_documentacao: 'Falta documentação', sem_equipe: 'Sem equipe ou tempo para a proposta', nao_serve: 'O edital não serve, afinal', outro: 'Outro' };
var LOGO = 'https://assets.modal.org.br/logo/png/modal_logo_simplificada_512px.png';
// nova e avisada aparecem como a mesma coisa na página ("ainda sem resposta"): a troca entre as duas não invalida a confirmação
function grupoSit(s) { return s === 'nova' || s === 'avisada' ? 'sem_resposta' : String(s || ''); }

// Pedido bruto -> pedido validado. metodo: 'GET' (query) ou 'POST' (body). Token de formato exato; decisão da lista.
function lerPedido(metodo, entrada) {
  var b = entrada && typeof entrada === 'object' ? entrada : {};
  var t = String(b.t || '').trim(), d = String(b.d || '').trim();
  var valido = /^[a-f0-9]{48}$/.test(t) && DECISOES.indexOf(d) >= 0;
  var opcoes = d === 'desistiu' ? OPCOES_DES : (d === 'nao_serve' ? OPCOES_NS : {});
  var opcao = Object.prototype.hasOwnProperty.call(opcoes, String(b.motivo_opcao || '')) ? String(b.motivo_opcao) : '';
  var motivo = metodo === 'POST' && (d === 'nao_serve' || d === 'desistiu') ? String(b.motivo || '').replace(/[\u0000-\u001f\u007f]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 500) : '';
  var s = String(b.s || '').trim();
  return {
    metodo: metodo === 'POST' ? 'POST' : 'GET', valido: valido, t: valido ? t : '', d: valido ? d : '', token_busca: valido ? t : 'token-invalido',
    motivo_opcao_rotulo: metodo === 'POST' && opcao ? opcoes[opcao] : '', motivo: motivo,
    mostrada: Object.prototype.hasOwnProperty.call(SIT_PAGINA, s) ? s : ''
  };
}

// a: linha da avaliação (ou vazia), op: linha da oportunidade. Devolve o que a página e a gravação precisam.
function decidir(p, a, op) {
  a = a || {}; op = op || {};
  var acao = 'confirmar', status = 200;
  if (!p.valido || !a.id || a.token !== p.t) return { acao: 'erro', status: 404 };
  if (FINAIS.indexOf(a.situacao) >= 0) { acao = 'bloqueada'; }
  else if (TRANS[p.d].indexOf(a.situacao) < 0) { acao = 'recusada'; status = 409; }
  else if (p.metodo === 'POST') {
    // grava só se a situação ainda for a que a página mostrou
    if (p.mostrada && grupoSit(p.mostrada) !== grupoSit(a.situacao)) { acao = 'mudou'; status = 409; }
    else acao = 'gravar';
  }
  var grava = ['concorrer', 'talvez', 'nao_serve'].indexOf(p.d) >= 0 ? 'decisao' : (p.d === 'enviada' ? 'envio' : 'resultado');
  var junta = function () { return [p.motivo_opcao_rotulo, p.motivo].filter(Boolean).join(': ') || 'Não informado'; };
  var i = infoOp(op);
  return {
    acao: acao, status: status, id: a.id, t: p.t, d: p.d, rotulo: ROT[p.d], grava: grava,
    motivo_gravar: p.d === 'nao_serve' ? junta() : '', motivo_desistencia: p.d === 'desistiu' ? junta() : '',
    situacao_atual: a.situacao, situacao_rotulo: SIT_PAGINA[a.situacao] || a.situacao, decidido_em_br: br(dia(a.resultado_em) || dia(a.decidido_em)),
    alternativas: Object.keys(TRANS).filter(function (d) { return d !== p.d && TRANS[d].indexOf(a.situacao) >= 0; }),
    op: { titulo: i.titulo, ofertante: i.ofertante, prazo_br: br(i.prazo), valor: i.valor, resumo: i.resumo, prog: i.prog, tg: i.link.tg, link: i.link.url, link_rotulo: i.link.rotulo },
    aval: { aderencia: a.aderencia, recomendacao: a.recomendacao, parcial: !!a.avaliacao_parcial, justificativa: txt(a.justificativa), projeto: txt(a.projeto_sugerido) }
  };
}

// Depois da gravação o fluxo relê a avaliação: só é "registrada" se a linha mostra a situação pedida. Se outra pessoa mudou antes, vira 409 sem afirmar sucesso.
function confirmarGravacao(D, releitura) {
  if (D.acao !== 'gravar') return D;
  var r = releitura || {};
  if (r.id === D.id && r.situacao === D.d) return D;
  return Object.assign({}, D, { acao: 'mudou', status: 409, situacao_atual: txt(r.situacao) || D.situacao_atual, situacao_rotulo: SIT_PAGINA[r.situacao] || D.situacao_rotulo });
}

function pagina(titulo, conteudo) {
  return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="referrer" content="no-referrer"><title>' + esc(titulo) + ' · Modal – Oportunidades</title><style>' +
    '*{box-sizing:border-box}body{margin:0;background:#f4f6fa;color:#1f2033;font-family:Ubuntu,Lato,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;font-size:16px;line-height:1.55}' +
    '.faixa{height:5px;background:#00004d}.caixa{max-width:640px;margin:0 auto;padding:16px}header img{display:block;width:180px;max-width:60%;height:auto;margin:8px 0 16px}' +
    '.cartao{background:#fff;border-radius:8px;padding:20px;box-shadow:0 1px 3px rgba(0,0,0,.1)}h1{font-size:24px;line-height:1.25;color:#00004d;margin:0 0 12px}.rotulo{font-size:13px;letter-spacing:1.2px;text-transform:uppercase;color:#666;margin:0 0 6px}' +
    '.op{background:#f4f6fa;border-left:4px solid #ff9900;padding:12px 14px;border-radius:6px;margin:16px 0}dl{margin:12px 0}dt{font-weight:700;color:#00004d;font-size:14px}dd{margin:0 0 8px}' +
    '.aviso{background:#fff4e0;border-radius:6px;padding:12px 14px;margin:16px 0}button{display:block;width:100%;min-height:48px;padding:14px;font:inherit;font-size:17px;font-weight:700;border:0;border-radius:6px;background:#00004d;color:#fff;cursor:pointer}' +
    'button:hover{background:#000033}a{color:#00004d;font-weight:700}a:focus-visible,button:focus-visible,input:focus-visible,textarea:focus-visible{outline:3px solid #ff9900;outline-offset:2px}' +
    'fieldset{border:1px solid #c9cde0;border-radius:6px;padding:8px 14px;margin:16px 0}legend{font-weight:700;color:#00004d;padding:0 4px}label.opcao{display:flex;gap:10px;align-items:center;min-height:44px}' +
    'label.texto{display:block;font-weight:700;color:#00004d;margin:12px 0 6px}textarea{width:100%;min-height:96px;font:inherit;padding:10px;border:1px solid #8a90ad;border-radius:6px}.outras{font-size:15px;margin-top:18px}footer{font-size:13px;color:#666;text-align:center;padding:16px}' +
    '</style></head><body><div class="faixa"></div><div class="caixa"><header><img src="' + LOGO + '" alt="Instituto Modal"></header><main class="cartao">' + conteudo + '</main><footer>Instituto Modal · modal.org.br</footer></div></body></html>';
}
function linksAlt(D, lista) { return lista.map(function (x) { return '<a href="' + esc(urlDecisao(D.t, x)) + '">' + ROT[x] + '</a>'; }).join(' · '); }
function blocoOp(D) {
  var o = D.op || {}, a = D.aval || {};
