}
function avisoPacote(D, confirmado) {
  return '<div class="aviso"><strong>Próximos passos:</strong> ' + (confirmado ? 'em alguns minutos' : 'ao confirmar, em alguns minutos') + ' a lista oportunidades@modal.org.br recebe o pacote de preparação: documentos que faltam, cronograma até o prazo e, quando o edital exigir, os links para emitir as certidões. Depois vêm lembretes até a entrega.</div>';
